code='''
    let uploadItem=null,uploadUrls=[];
    function renderAssociatedPhotos(){const paths=$('edit-imagenes').value.split(/\\r?\\n/).map(p=>p.trim()).filter(Boolean);$('associated-photos').replaceChildren();paths.forEach((path,index)=>{const tile=el('div','photo-tile'),img=el('img');img.src=path;img.alt=`Fotografía ${index+1}`;tile.append(img,el('p','',index===0?'Portada':`Fotografía ${index+1}`));const cover=el('button','btn','Usar como portada');cover.type='button';cover.disabled=index===0;cover.addEventListener('click',()=>{const reordered=[path,...paths.filter((p,i)=>i!==index)];$('edit-imagenes').value=reordered.join('\\n');renderAssociatedPhotos();});const remove=el('button','btn danger','Quitar asociación');remove.type='button';remove.addEventListener('click',()=>{$('edit-imagenes').value=paths.filter((p,i)=>i!==index).join('\\n');renderAssociatedPhotos();});tile.append(cover,remove);$('associated-photos').append(tile);});}
    function clearUploadPreviews(){uploadUrls.forEach(u=>URL.revokeObjectURL(u));uploadUrls=[];$('upload-previews').replaceChildren();}
    function openUpload(item){uploadItem=item;$('upload-files').value='';clearUploadPreviews();$('upload-error').hidden=true;$('upload-target').textContent=`${item.nombre} · ID ${item.id} · Carpeta: imagenes/${item.id}/`;if(!serverInventory){$('upload-error').textContent='Para subir y guardar fotografías, abre esta galería desde XAMPP y usa el inventario del servidor.';$('upload-error').hidden=false;}$('submit-upload').disabled=!serverInventory;$('photo-upload').showModal();}
    $('upload-product').addEventListener('click',()=>openUpload(activeItem));$('upload-editor').addEventListener('click',()=>openUpload(editingItem));['close-upload','cancel-upload'].forEach(id=>$(id).addEventListener('click',()=>{if(!$('submit-upload').disabled||!serverInventory)$('photo-upload').close();}));$('photo-upload').addEventListener('close',clearUploadPreviews);
    $('upload-files').addEventListener('change',()=>{clearUploadPreviews();[...$('upload-files').files].forEach(file=>{const tile=el('div','photo-tile');if(['image/jpeg','image/png','image/webp'].includes(file.type)){const url=URL.createObjectURL(file);uploadUrls.push(url);const img=el('img');img.src=url;img.alt=file.name;tile.append(img);}tile.append(el('p','',`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB`));$('upload-previews').append(tile);});});
    $('upload-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('submit-upload');if(!serverInventory)return;button.disabled=true;$('upload-error').hidden=true;try{const files=[...$('upload-files').files];if(!files.length||files.length>10)throw new Error('Selecciona entre 1 y 10 fotografías.');if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024))throw new Error('Usa JPG, PNG o WebP de hasta 8 MB por fotografía.');const form=new FormData();form.append('id',uploadItem.id);form.append('revision',revision);files.forEach(f=>form.append('imagenes[]',f));const response=await fetch('subir_imagenes.php',{method:'POST',headers:{'X-Inventory-Token':saveToken},body:form});let result;try{result=await response.json();}catch(e){throw new Error('El servidor no pudo recibir las fotografías. Revisa el límite de tamaño de XAMPP.');}if(!response.ok)throw new Error(result.error||'No se pudo subir.');revision=result.revision;setInventory(result.inventario);if($('editor').open){const current=$('edit-imagenes').value.split(/\\r?\\n/).map(p=>p.trim()).filter(Boolean);$('edit-imagenes').value=[...current,...result.imagenes].join('\\n');renderAssociatedPhotos();}openPreview(items.find(i=>i.id===uploadItem.id));$('photo-upload').close();showNotice(`${result.imagenes.length} fotografías guardadas y asociadas al producto.`);}catch(error){$('upload-error').textContent=error.message;$('upload-error').hidden=false;}finally{button.disabled=false;}});
'''
